'use strict';

const { Benchmark } = require('benchmark');

const stream = {
    write() {
        // nothing to do
    },
};

const jsonLogger = require('..')({
    name: 'yandex-logger',
    streams: [
        {
            level: 'info',
            stream: require('../streams/json')({ stream }),
        },
    ],
});

const stdLogger = require('..')({
    name: 'yandex-logger',
    streams: [
        {
            level: 'info',
            stream: require('../streams/line')({ stream }),
        },
    ],
});

const qloudLogger = require('..')({
    name: 'yandex-logger',
    streams: [
        {
            level: 'info',
            stream: require('../streams/qloud')({ stream }),
        },
    ],
});

const sentryLogger = require('..')({
    name: 'yandex-logger',
    streams: [
        {
            level: 'info',
            stream: require('../streams/sentry')({
                dsn: 'http://user:pass@localhost:9000/2',
            }),
        },
    ],
});

const data = {
    x: 1,
    y: 2,
    z: {
        x: 1,
        y: 2,
        z: [1, 2],
    },
};
const message = 'Something bad!';
const err = new TypeError('undefined is not a function');

let suite = new Benchmark.Suite('Logger');
suite
    .add('[json] Simple message', () => {
        jsonLogger.info(message);
    })
    .add('[json] Message and data', () => {
        jsonLogger.info({ data }, message);
    })
    .add('[json] Error', () => {
        jsonLogger.error({ err });
    })
    .add('[std] Simple message', () => {
        stdLogger.info(message);
    })
    .add('[std] Message and data', () => {
        stdLogger.info({ data }, message);
    })
    .add('[std] Error', () => {
        stdLogger.error({ err });
    })
    .add('[qloud] Simple message', () => {
        qloudLogger.info(message);
    })
    .add('[qloud] Message and data', () => {
        qloudLogger.info({ data }, message);
    })
    .add('[qloud] Error', () => {
        qloudLogger.error({ err }, message);
    })
    .add('[sentry] Simple message', () => {
        sentryLogger.info(message);
    })
    .add('[sentry] Message and data', () => {
        sentryLogger.info({ data }, message);
    })
    .add('[sentry] Error', () => {
        sentryLogger.error({ err }, message);
    })
    .on('cycle', event => console.warn(String(event.target)))
    .on('error', err => console.warn('Ошибка!', err))
    .run();
